using Microsoft.AspNetCore.Components;

namespace sv_85a3a3e8d7e74b0f901503bcfcda7ed9.Services;

/// <summary>
/// Scoped service that owns the mutable theme state for a single circuit.
/// Mutate via SetThemeAsync / SetAccentColorAsync, which push updates to both
/// the event subscribers and the CascadingValueSource so that every
/// component (static or interactive) re-renders.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeInfo> _source;

    public ThemeService(CascadingValueSource<ThemeInfo> source)
    {
        _source = source;
    }

    public ThemeInfo Current { get; } = new();

    public event Action? OnChange;

    public async Task SetThemeAsync(Theme theme)
    {
        Current.Theme = theme;
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string color)
    {
        Current.AccentColor = color;
        await NotifyAsync();
    }

    private async Task NotifyAsync()
    {
        OnChange?.Invoke();
        await _source.NotifyChangedAsync(Current);
    }
}

