toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                var isActive = ThemeService.Current.Theme == t;
                <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => SetThemeAsync(t)">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <input type="color"
               class="form-control form-control-color mb-3"
               value="@ThemeService.Current.AccentColor"
               @onchange="OnAccentChangedAsync" />

        <p class="text-muted mb-0">
            Current: <strong>@ThemeService.Current.Theme</strong> /
            <span style="color: @ThemeService.Current.AccentColor;">@ThemeService.Current.AccentColor</span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private async Task SetThemeAsync(Theme theme)
    {
        await ThemeService.SetThemeAsync(theme);
    }

    private async Task OnAccentChangedAsync(ChangeEventArgs e)
    {
        await ThemeService.SetAccentColorAsync(e.Value?.ToString() ?? "#0d6efd");
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

